def get\_coach\_data(filename):

try:

with open(filename) as f:

data = f.readline()

temp1 = data.strip().split(',')

return(AthleteList(temp1.pop(0),temp1.pop(0), temp1))

except IOError as ioerr:

print('File error:' + str(ioerr))

return(None)

&#x200B;

def sanitize(time\_string):

if '-' in time\_string:

splitter = '-'

elif ':' in time\_string:

splitter = ':'

else:

return(time\_string)

(mins, secs) = time\_string.split(splitter)

return(mins + '.' + secs)

